("treat","침·약침·추나·한약 치료는 어떻게 하나요?",H3("1. 침 치료")+"\n"+UL([B("신수(腎兪)","둘째 허리뼈 가시돌기 아래에서 양옆으로 손가락 두 마디쯤 떨어진 곳입니다."),B("환도(環跳)","옆으로 누워 다리를 굽혔을 때 엉덩이 옆 큰 뼈 뒤쪽의 오목한 곳으로, 다리 저림에 씁니다."),B("위중(委中)","무릎을 굽힐 때 접히는 오금 가로 주름의 정중앙입니다."),B("곤륜(崑崙)","바깥 복사뼈와 아킬레스힘줄 사이의 오목한 곳입니다.")])+"\n"+P("수술 흉터와 고정 나사가 있는 마디 위에는 직접 깊게 놓지 않고, 그 옆과 엉덩이, 다리의 혈을 씁니다. 차고 뻣뻣한 허리에는 온열 요법을 시행합니다.")+"\n"+H3("2. 약침·초음파 가이드 약침과 추나 요법")+"\n"+P("약침은 일반 약침과 초음파 가이드 약침을 모두 시행하며, 아픈 부위의 깊이와 주변 구조에 따라 진찰 후 골라 씁니다. 초음파 가이드 약침은 초음파 화면으로 바늘 끝을 확인하면서 놓는 방식입니다. 초음파로 흉터 주변 다열근과 척추세움근이 뭉친 자리, 신경이 지나는 깊이, 고정 나사와의 거리를 확인하고, 수술한 마디는 피해 옆 근육과 엉치 관절 인대에 바늘 끝이 닿도록 놓습니다. 골반과 위아래 마디가 틀어져 허리가 한쪽으로 쏠린 경우 진찰 후 추나 요법을 시행하며, 수술한 마디에는 뼈 유합이 끝나고 수술 의사가 확인하기 전까지 하지 않습니다.")+"\n"+H3("3. 한약")+"\n"+P("유형에 따라 남은 어혈을 풀거나, 약해진 기혈과 간신을 채우는 탕약을 처방합니다. 진통제, 신경통 약, 항응고제처럼 드시는 약은 알려 주시면 확인해 처방합니다. 임신 중이거나 간·신장 질환, 출혈 경향이 있다면 진료 때 꼭 알려 주세요. 확인 후 안전한 약재로 처방합니다.")),
("road","관리는 어떤 순서로 진행되나요?",ROAD([("원인 확인","수술 병원 영상과 신경 검사로 재수술이 필요한 문제가 없는지 먼저 봅니다."),("통증 낮추기","침·약침으로 흉터 주변 근육과 엉치 관절의 통증을 줄입니다."),("움직임 되찾기","위아래 마디와 골반의 균형을 추나로 바로잡고 걷는 거리를 늘립니다."),("버티는 힘 기르기","깊은 허리 근육 운동과 한약으로 다시 아프지 않을 바탕을 만듭니다.")])),
